find:
// The descriptor closes before the admission is released.
if f != nil {
	_ = f.Close()
}
r.mu.Lock()
r.active--
var wake chan struct{}
if len(r.queued) > 0 {
	wake = r.queued[0]
	r.queued = r.queued[1:]
}
r.mu.Unlock()
if wake != nil {
	close(wake)
}

